// Solo llegan filas que Postgres ya determino huerfanas (sin trabajo que
// las referencie, con mas de 2 horas de generadas). Antes de borrar nada,
// se valida que la ruta matchee EXACTAMENTE el patron que el propio
// workflow 04 usa para escribir estos PNG -- asi nunca se llama a
// fs.unlinkSync con una ruta inesperada. n8n no trae aca el nodo
// "Execute Command" (deshabilitado por seguridad), asi que el borrado se
// hace con fs directo -- requiere NODE_FUNCTION_ALLOW_BUILTIN=fs en el
// servicio n8n de docker-compose.yml.
const fs = require('fs')
const PATTERN = /^\/files\/mailingai\/out\/[A-Za-z0-9_.-]+\.png$/
const results = []
for (const item of $input.all()) {
  const path = item.json.output_file
  if (!PATTERN.test(path)) {
    results.push({ json: { output_file: path, deleted: false, reason: 'ruta no matchea el patron esperado' } })
    continue
  }
  try {
    fs.unlinkSync(path)
    results.push({ json: { output_file: path, deleted: true } })
  } catch (err) {
    // ENOENT (el archivo ya no existe) no es un error real para este job de
    // limpieza -- la fila en Postgres ya quedo borrada de todas formas.
    results.push({ json: { output_file: path, deleted: err.code === 'ENOENT', reason: err.code } })
  }
}
return results
